---进入猫车活动
function OverseaClubCatCarUtils:CatCatEntry()
    ---@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local playerUID = playerComponent.playerDojo.playerId
    local recordedScheduleId = PlayerPrefsUtility.GetEncryptedInt(playerUID .. CatCarScheduleId, -1)
    local clubHomeDojo  = ClubUtils.GetClubComp():GetHomeDojo()
    
    if checkNumber(clubHomeDojo.carScheduleId) ~= recordedScheduleId then
        PlayerPrefsUtility.SetEncryptedInt(playerUID .. CatCarScheduleId, clubHomeDojo.carScheduleId or 0)
        UIRaycastBlocker:AddCondition(OverseaClubCatCarUtils.StartEntryDialogBlocker)
        CfUtils.DialogOpen(Constants.UITypeIds.OverseaClubCatCarStartEntryDialog)
    else
        UIRaycastBlocker:AddCondition(OverseaClubCatCarUtils.StartEntryDialogBlocker)
        GameUtils.ShowBlackOverlay(nil,function()
            CoYield(1)
            CfUtils.DialogOpen(Constants.UITypeIds.OverseaClubCatCarBackgroundDialog,nil, {
                UIArgs(Constants.UITypeIds.UIOverseaClubHallDialog),
                UIArgs(Constants.UITypeIds.UIOverseaClubActivityDialog)
            })
        end,function() 
            UIRaycastBlocker:RemoveCondition(OverseaClubCatCarUtils.StartEntryDialogBlocker)
            Events.Broadcast(ClubUtils.EventName.Loading_End)
        end ,"Prefabs/OverClub/CommonTransition2.prefab")
    end
    
end

function OverseaClubCatCarUtils:GetCurSpeedGradeVo(points)
    if self.speedGradeVos == nil then
        ---@type ClubCatCarSpeedGradeVo[]
        self.speedGradeVos = checkTable(CfUtils.GetCf(AutoIds.IdSetting6281,"ClubCatCarSpeedGradeVo",true))
    end
    for i = #self.speedGradeVos,1,-1 do
        local vo = self.speedGradeVos[i]
        if points >= vo.mileage then
            return vo
        end
    end
    
    return self.speedGradeVos[1]
end

function OverseaClubCatCarUtils:GetNextSpeedGradeVo(points)
    if self.speedGradeVos == nil then
        ---@type ClubCatCarSpeedGradeVo[]
        self.speedGradeVos = checkTable(CfUtils.GetCf(AutoIds.IdSetting6281,"ClubCatCarSpeedGradeVo",true))
    end
    for i = 1,#self.speedGradeVos do
        local vo = self.speedGradeVos[i]
        if points < vo.mileage then
            return vo
        end
    end
    return nil
end

---@param callConfs OverseaClubCatCarDojo.CallConf[]
---@return OverseaClubCatCarScrapeRewardNode.InputData
function OverseaClubCatCarUtils:GroupCallConfByType(callConfs)
    local rewardGroups = {}
    for i, v in pairs(callConfs) do
        local type = v.type --几等奖
        if rewardGroups[type] == nil then
            rewardGroups[type] = {
                type = type,
                rewardList = {}
            }
        end
        table.insert(rewardGroups[type].rewardList, v)
    end
    local result = {}
    for i, v in pairs(rewardGroups) do
        table.insert(result, v)
    end
    return result
end

