---今天是活动第几天
function OverseaClubCatCarUtils:GetTodayIndex()
    local startTime = ClubUtils.GetClubComp():GetHomeDojo().carStartTime
    local curTime = GameUtils.GetServerTime() and GameUtils.GetServerTime() or os.time()
    local index  = math.floor((curTime - startTime) / 86400) + 1
    --index 最大为7
    return (index -1) % 7 + 1
end

